  // Line 1: 2 * 8500 = 17000, discount = 1700, after = 15300, VAT = 3213
  // Line 2: 2 * 9500 = 19000, discount = 3800, after = 15200, VAT = 3192
  // Subtotal = 36000, discount = 5500, VAT = 6405, total = 36000 - 5500 + 6405 = 36905
  assert.equal(totals.subtotal, 36000);
