  // Line 1: 980, no discount, VAT = 980 * 21% = 205.8 -> 206
  // Line 2: 3700, no discount, VAT = 3700 * 9% = 333
  // Total = 980 + 3700 + 206 + 333 = 5219
  assert.equal(totals.subtotal, 4680);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 539);
  assert.equal(totals.total, 5219);
});

